using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;using System.Net.Http.Json;
namespace RaceDay.Mvc.Controllers;
public class EventsController(RaceDayApiClient api):Controller
{
 string? Cookie=>HttpContext.Session.GetString("ApiCookie");string Role=>HttpContext.Session.GetString("Role")??"";
 IActionResult NeedLogin()=>RedirectToAction("Login","Account");
 public async Task<IActionResult> Index(string? eventType,string? search){if(Cookie==null)return NeedLogin();using var r=await api.Send(HttpMethod.Get,"api/events",Cookie);if(!r.IsSuccessStatusCode){TempData["Error"]=await RaceDayApiClient.Error(r);return View(new List<EventDto>());}var list=await r.Content.ReadFromJsonAsync<List<EventDto>>()??new();if(!string.IsNullOrWhiteSpace(eventType))list=list.Where(e=>e.EventType.Equals(eventType,StringComparison.OrdinalIgnoreCase)).ToList();if(!string.IsNullOrWhiteSpace(search))list=list.Where(e=>e.EventName.Contains(search,StringComparison.OrdinalIgnoreCase)||e.Location.Contains(search,StringComparison.OrdinalIgnoreCase)).ToList();if(Role=="Organiser"){using var me=await api.Send(HttpMethod.Get,"api/users/me",Cookie);if(me.IsSuccessStatusCode){var u=await me.Content.ReadFromJsonAsync<UserDto>();list=list.Where(e=>e.OrganiserId==u?.UserId).ToList();}}return View(list);}
 public async Task<IActionResult> Details(int id){if(Cookie==null)return NeedLogin();using var r=await api.Send(HttpMethod.Get,$"api/events/{id}",Cookie);if(!r.IsSuccessStatusCode){TempData["Error"]=await RaceDayApiClient.Error(r);return RedirectToAction(nameof(Index));}using var categories=await api.Send(HttpMethod.Get,$"api/events/{id}/categories",Cookie);if(categories.IsSuccessStatusCode){ViewBag.Categories=await categories.Content.ReadFromJsonAsync<List<CategoryDto>>()??new();}else{ViewBag.Categories=new List<CategoryDto>();TempData["Error"]="Event details loaded, but categories could not be loaded: "+await RaceDayApiClient.Error(categories);}return View(await r.Content.ReadFromJsonAsync<EventDto>());}
 [HttpGet] public IActionResult Create(){if(Cookie==null)return NeedLogin();if(Role!="Organiser")return Forbid();return View(new EventVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(EventVm vm){if(Cookie==null)return NeedLogin();if(Role!="Organiser")return Forbid();if(!ModelState.IsValid)return View(vm);using var r=await api.Send(HttpMethod.Post,"api/events",Cookie,new {eventName=vm.EventName,description=vm.Description,eventDate=vm.EventDate,location=vm.Location,distanceKm=vm.DistanceKm,eventType=vm.EventType});if(!r.IsSuccessStatusCode){ModelState.AddModelError("",await RaceDayApiClient.Error(r));return View(vm);}var ev=await r.Content.ReadFromJsonAsync<EventDto>();if(vm.BannerImage!=null&&ev!=null){using var up=await api.Send(HttpMethod.Post,$"api/events/{ev.EventId}/banner",Cookie,file:vm.BannerImage);if(!up.IsSuccessStatusCode)TempData["Error"]="Event created, but banner upload failed: "+await RaceDayApiClient.Error(up);}TempData["Success"]="Your event has been created.";return RedirectToAction(nameof(Details),new{id=ev?.EventId});}
 [HttpGet] public async Task<IActionResult> Edit(int id){if(Cookie==null)return NeedLogin();using var r=await api.Send(HttpMethod.Get,$"api/events/{id}",Cookie);if(!r.IsSuccessStatusCode)return NotFound();var e=await r.Content.ReadFromJsonAsync<EventDto>();if(e==null)return NotFound();return View(new EventVm{EventId=e.EventId,EventName=e.EventName,Description=e.Description,EventDate=e.EventDate,Location=e.Location,DistanceKm=e.DistanceKm,EventType=e.EventType});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,EventVm vm){if(Cookie==null)return NeedLogin();if(!ModelState.IsValid)return View(vm);using var r=await api.Send(HttpMethod.Put,$"api/events/{id}",Cookie,new{eventName=vm.EventName,description=vm.Description,eventDate=vm.EventDate,location=vm.Location,distanceKm=vm.DistanceKm,eventType=vm.EventType});if(!r.IsSuccessStatusCode){ModelState.AddModelError("",await RaceDayApiClient.Error(r));return View(vm);}if(vm.BannerImage!=null){using var up=await api.Send(HttpMethod.Post,$"api/events/{id}/banner",Cookie,file:vm.BannerImage);if(!up.IsSuccessStatusCode)TempData["Error"]=await RaceDayApiClient.Error(up);}TempData["Success"]="Event updated.";return RedirectToAction(nameof(Details),new{id});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){if(Cookie==null)return NeedLogin();using var r=await api.Send(HttpMethod.Delete,$"api/events/{id}",Cookie);TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Event deleted.":await RaceDayApiClient.Error(r);return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Enrol(int id,int categoryId){if(Cookie==null)return NeedLogin();using var r=await api.Send(HttpMethod.Post,$"api/events/{id}/enrolments",Cookie,new{categoryId});TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"You are enrolled!":await RaceDayApiClient.Error(r);return RedirectToAction(nameof(Details),new{id});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddCategory(int id,CategoryVm vm){if(Cookie==null)return NeedLogin();if(!ModelState.IsValid)return RedirectToAction(nameof(Details),new{id});using var r=await api.Send(HttpMethod.Post,$"api/events/{id}/categories",Cookie,new{categoryName=vm.CategoryName,minAge=vm.MinAge,maxAge=vm.MaxAge});TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Category added.":await RaceDayApiClient.Error(r);return RedirectToAction(nameof(Details),new{id});}
 [HttpGet] public async Task<IActionResult> Enrolments(int id){if(Cookie==null)return NeedLogin();using var r=await api.Send(HttpMethod.Get,$"api/events/{id}/enrolments",Cookie);if(!r.IsSuccessStatusCode){TempData["Error"]=await RaceDayApiClient.Error(r);return RedirectToAction(nameof(Details),new{id});}var viewModel=new EventEnrolmentsVm{EventId=id,Enrolments=await r.Content.ReadFromJsonAsync<List<EnrolmentDto>>()??new()};using var results=await api.Send(HttpMethod.Get,$"api/events/{id}/results",Cookie);if(results.IsSuccessStatusCode){var items=await results.Content.ReadFromJsonAsync<List<ResultDto>>()??new();viewModel.ResultsByEnrolment=items.ToDictionary(x=>x.EnrolmentId);}else{TempData["Error"]="Could not load recorded results: "+await RaceDayApiClient.Error(results);}return View(viewModel);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CaptureResult(int id,int eventId,ResultVm vm){if(Cookie==null)return NeedLogin();if(!TimeSpan.TryParse(vm.FinishTime,out var time)){TempData["Error"]="Enter a valid finish time (hh:mm:ss).";return RedirectToAction(nameof(Enrolments),new{id});}using var r=await api.Send(HttpMethod.Post,$"api/enrolments/{id}/results",Cookie,new{finishTime=time,finishPosition=vm.FinishPosition});TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Result saved.":await RaceDayApiClient.Error(r);return RedirectToAction(nameof(Enrolments),new{id=eventId});}
}
